<?php

declare(strict_types=1);

namespace App\Controller\Admin;

use Alchemy\AclBundle\Admin\PermissionView;
use App\Security\Acl\FormSchemaAclObject;
use App\Security\Acl\TargetDataAclObject;
use EasyCorp\Bundle\EasyAdminBundle\Attribute\AdminRoute;
use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;
use Symfony\Component\HttpFoundation\Response;

/**
 * The permissions that only exist on every target at once: editing their forms, editing their data.
 *
 * Routes are generated by EasyAdmin under the dashboard prefix ("easyadmin_global_permissions_*").
 */
#[AdminRoute('/global-permissions', name: 'global_permissions')]
final class GlobalPermissionsController extends AbstractController
{
    public const string ROUTE_FORM_SCHEMA = 'easyadmin_global_permissions_form_schema';
    public const string ROUTE_TARGET_DATA = 'easyadmin_global_permissions_target_data';

    public function __construct(
        private readonly PermissionView $permissionView,
    ) {
    }

    #[AdminRoute('/form-schema', name: 'form_schema')]
    public function formSchema(): Response
    {
        return $this->renderPermissions(FormSchemaAclObject::OBJECT_KEY);
    }

    #[AdminRoute('/target-data', name: 'target_data')]
    public function targetData(): Response
    {
        return $this->renderPermissions(TargetDataAclObject::OBJECT_KEY);
    }

    private function renderPermissions(string $objectKey): Response
    {
        return $this->render('@AlchemyAcl/easyadmin/permissions.html.twig', $this->permissionView->getViewParameters($objectKey, null));
    }
}
